[[nodiscard]] bool TestHideNamesCommands(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"hide_names_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create hide-names test root.");

    state.Require(SelfTest::WriteTextFile(root / L"a.txt", "a"), L"Failed to create a.txt.");
    state.Require(SelfTest::WriteTextFile(root / L"b.log", "b"), L"Failed to create b.log.");
    state.Require(SelfTest::WriteTextFile(root / L"c.txt", "c"), L"Failed to create c.txt.");

    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const auto restorePath                                = wil::scope_exit([&]
    {
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);

    const bool showHiddenBefore = g_folderWindow.GetShowHiddenFiles();
    const bool showSystemBefore = g_folderWindow.GetShowSystemFiles();
    const auto restoreViewFlags = wil::scope_exit([&]
    {
        g_folderWindow.SetShowHiddenFiles(showHiddenBefore);
        g_folderWindow.SetShowSystemFiles(showSystemBefore);
    });

    g_folderWindow.SetShowHiddenFiles(true);
    g_folderWindow.SetShowSystemFiles(true);

    std::atomic<uint32_t> enumCount{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumCount.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Failed to set pane path for hide-names test.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {L"a.txt", L"b.log", L"c.txt"}, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Pane contents not ready for hide-names test.");

    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"Expected a.txt visible before hiding names.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"b.log"), L"Expected b.log visible before hiding names.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"c.txt"), L"Expected c.txt visible before hiding names.");

    // Hide Selected Names
    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(
        FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"a.txt" || name == L"c.txt"; }, true);
    {
        const uint32_t before = enumCount.load(std::memory_order_acquire);
        FocusFolderViewPane(FolderWindow::Pane::Left);
        SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SELECTION_HIDE_SELECTED_NAMES, 0), 0);
        state.Require(WaitForAtomicAtLeast(enumCount, before + 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                      L"Enumeration did not refresh after Hide Selected Names.");
    }

    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"a.txt should be hidden after Hide Selected Names.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"b.log"), L"b.log should remain visible after Hide Selected Names.");
    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"c.txt"), L"c.txt should be hidden after Hide Selected Names.");
    state.Require(g_folderWindow.DebugIsNameFilterActive(FolderWindow::Pane::Left), L"Expected filter indicator active after hiding names.");

    // Show Hidden Names (clears hidden set)
    {
        const uint32_t before = enumCount.load(std::memory_order_acquire);
        FocusFolderViewPane(FolderWindow::Pane::Left);
        SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SELECTION_SHOW_HIDDEN_NAMES, 0), 0);
        state.Require(WaitForAtomicAtLeast(enumCount, before + 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                      L"Enumeration did not refresh after Show Hidden Names.");
    }

    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"a.txt should be visible after Show Hidden Names.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"b.log"), L"b.log should be visible after Show Hidden Names.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"c.txt"), L"c.txt should be visible after Show Hidden Names.");
    state.Require(! g_folderWindow.DebugIsNameFilterActive(FolderWindow::Pane::Left), L"Filter indicator should be inactive after Show Hidden Names.");

    // Hide Unselected Names (requires at least one selected item)
    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"b.log"; }, true);
    {
        const uint32_t before = enumCount.load(std::memory_order_acquire);
        FocusFolderViewPane(FolderWindow::Pane::Left);
        SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SELECTION_HIDE_UNSELECTED_NAMES, 0), 0);
        state.Require(WaitForAtomicAtLeast(enumCount, before + 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                      L"Enumeration did not refresh after Hide Unselected Names.");
    }

    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"a.txt should be hidden after Hide Unselected Names.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"b.log"), L"b.log should remain visible after Hide Unselected Names.");
    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"c.txt"), L"c.txt should be hidden after Hide Unselected Names.");

    // Clear hidden names again
    {
        const uint32_t before = enumCount.load(std::memory_order_acquire);
        FocusFolderViewPane(FolderWindow::Pane::Left);
        SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SELECTION_SHOW_HIDDEN_NAMES, 0), 0);
        state.Require(WaitForAtomicAtLeast(enumCount, before + 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                      L"Enumeration did not refresh after clearing hidden names.");
    }

    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"a.txt should be visible after clearing hidden names.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"b.log"), L"b.log should be visible after clearing hidden names.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"c.txt"), L"c.txt should be visible after clearing hidden names.");

    // Verify that Show Hidden Names does not clear the pane filter.
    {
        const uint32_t before = enumCount.load(std::memory_order_acquire);

        PaneFilterDialogAutomationState dlg{};
        std::jthread okCloser([&](std::stop_token) noexcept { AutomatePaneFilterDialog(mainWindow, dlg, true, L"*.txt", true); });
        FocusFolderViewPane(FolderWindow::Pane::Left);
        SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_LEFT_FILTER, 0), 0);
        okCloser.join();

        state.Require(dlg.sawDialog.load(std::memory_order_acquire), L"Pane Filter dialog did not open.");
        state.Require(dlg.closed.load(std::memory_order_acquire), L"Pane Filter dialog did not close after OK.");

        state.Require(WaitForAtomicAtLeast(enumCount, before + 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                      L"Enumeration did not refresh after applying pane filter.");
    }

    state.Require(g_folderWindow.DebugIsNameFilterActive(FolderWindow::Pane::Left), L"Filter expected active after applying a pane filter mask.");
    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"b.log"), L"b.log expected to be filtered out by pane filter.");

    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"a.txt"; }, true);
    {
        const uint32_t before = enumCount.load(std::memory_order_acquire);
        FocusFolderViewPane(FolderWindow::Pane::Left);
        SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SELECTION_HIDE_SELECTED_NAMES, 0), 0);
        state.Require(WaitForAtomicAtLeast(enumCount, before + 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                      L"Enumeration did not refresh after hiding a.txt while pane filter is active.");
    }

    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"a.txt should be hidden while pane filter is active.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"c.txt"), L"c.txt should remain visible while pane filter is active.");
    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"b.log"),
                  L"b.log should remain filtered out while pane filter is active.");

    {
        const uint32_t before = enumCount.load(std::memory_order_acquire);
        FocusFolderViewPane(FolderWindow::Pane::Left);
        SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SELECTION_SHOW_HIDDEN_NAMES, 0), 0);
        state.Require(WaitForAtomicAtLeast(enumCount, before + 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                      L"Enumeration did not refresh after showing hidden names while pane filter is active.");
    }

    const FolderView::NameFilterState filterState = g_folderWindow.DebugGetNameFilterState(FolderWindow::Pane::Left);
    state.Require(filterState.enabled, L"Pane filter expected to remain enabled after Show Hidden Names.");
    state.Require(filterState.text == L"*.txt", L"Pane filter text expected to remain '*.txt' after Show Hidden Names.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"a.txt should be visible after Show Hidden Names.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"c.txt"), L"c.txt should be visible after Show Hidden Names.");
    state.Require(! g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"b.log"), L"b.log should remain filtered out after Show Hidden Names.");

    // Clean up: disable pane filter.
    {
        const uint32_t before = enumCount.load(std::memory_order_acquire);

        PaneFilterDialogAutomationState dlg{};
        std::jthread okCloser([&](std::stop_token) noexcept { AutomatePaneFilterDialog(mainWindow, dlg, false, L"*.txt", true); });
        FocusFolderViewPane(FolderWindow::Pane::Left);
        SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_LEFT_FILTER, 0), 0);
        okCloser.join();

        state.Require(dlg.sawDialog.load(std::memory_order_acquire), L"Pane Filter dialog did not reopen for disable.");
        state.Require(dlg.closed.load(std::memory_order_acquire), L"Pane Filter dialog did not close after disabling.");

        state.Require(WaitForAtomicAtLeast(enumCount, before + 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                      L"Enumeration did not refresh after disabling pane filter.");
    }

    state.Require(! g_folderWindow.DebugIsNameFilterActive(FolderWindow::Pane::Left), L"Expected filter indicator inactive after disabling pane filter.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"a.txt"), L"a.txt should be visible after disabling pane filter.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"b.log"), L"b.log should be visible after disabling pane filter.");
    state.Require(g_folderWindow.DebugHasItemDisplayName(FolderWindow::Pane::Left, L"c.txt"), L"c.txt should be visible after disabling pane filter.");

    return state.failure.empty();
}

[[nodiscard]] bool TestSelectionSaveRestoreCommands(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"selection_save_restore_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create selection-save/restore test root.");

    state.Require(SelfTest::WriteTextFile(root / L"a.txt", "a"), L"Failed to create a.txt.");
    state.Require(SelfTest::WriteTextFile(root / L"b.log", "b"), L"Failed to create b.log.");
    state.Require(SelfTest::WriteTextFile(root / L"c.txt", "c"), L"Failed to create c.txt.");

    const std::optional<std::filesystem::path> leftBefore  = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const std::optional<std::filesystem::path> rightBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Right);
    const auto restorePath                                 = wil::scope_exit([&]
    {
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
        if (rightBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Right, rightBefore.value());
        }
    });

    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Right);
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to set local file-system plugin for left pane in selection-save/restore test.");
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Right, L"builtin/file-system")),
                  L"Failed to set local file-system plugin for right pane in selection-save/restore test.");

    std::atomic<uint32_t> enumLeft{0};
    std::atomic<uint32_t> enumRight{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumLeft.fetch_add(1u, std::memory_order_release);
        }
    });
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Right,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumRight.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallbacks = wil::scope_exit([&]
    {
        g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {});
        g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Right, {});
    });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Failed to set left pane path for selection-save/restore test.");
    state.Require(WaitForAtomicAtLeast(enumLeft, 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Left pane enumeration did not complete for selection-save/restore test.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {L"a.txt", L"b.log", L"c.txt"}, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Left pane contents not ready for selection-save/restore test.");

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Right, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Right, root, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Failed to set right pane path for selection-save/restore test.");
    state.Require(WaitForAtomicAtLeast(enumRight, 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Right pane enumeration did not complete for selection-save/restore test.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Right, {L"a.txt", L"b.log", L"c.txt"}, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Right pane contents not ready for selection-save/restore test.");

    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(
        FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"a.txt" || name == L"c.txt"; }, true);
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt"), L"Expected a.txt selected before save-selection.");
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt"), L"Expected c.txt selected before save-selection.");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 2u, L"Expected 2 selected items before save-selection.");

    FocusFolderViewPane(FolderWindow::Pane::Left);
    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SAVE_SELECTION, 0), 0);
    state.Require(g_folderWindow.HasSavedSelection(), L"Expected a saved selection after Save Selection command.");

    {
        const std::wstring clipText = ReadClipboardUnicodeText(mainWindow);

        state.Require(! clipText.empty(), L"Expected Save Selection to place Unicode text in the clipboard.");
        state.Require(clipText.find(L"a.txt") != std::wstring::npos, L"Expected clipboard text to contain a.txt.");
        state.Require(clipText.find(L"c.txt") != std::wstring::npos, L"Expected clipboard text to contain c.txt.");
    }

    // Rename c.txt to change casing before restore-selection, so restore must fall back to case-insensitive match.
    {
        const std::filesystem::path tempName = root / L"c_case_tmp.txt";
        std::filesystem::rename(root / L"c.txt", tempName, ec);
        state.Require(! ec, L"Failed to rename c.txt for case-insensitive restore-selection scenario.");

        std::filesystem::rename(tempName, root / L"C.TXT", ec);
        state.Require(! ec, L"Failed to rename temp file to C.TXT for case-insensitive restore-selection scenario.");

        const uint32_t before = enumRight.load(std::memory_order_acquire);
        g_folderWindow.CommandRefresh(FolderWindow::Pane::Right);
        state.Require(WaitForAtomicAtLeast(enumRight, before + 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                      L"Right pane did not refresh after renaming c.txt for case-insensitive restore-selection scenario.");
    }

    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Right, [](std::wstring_view) noexcept { return false; }, true);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Right) == 0u, L"Expected no selection in right pane before restore-selection.");

    FocusFolderViewPane(FolderWindow::Pane::Right);
    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SELECTION_RESTORE, 0), 0);

    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Right, L"a.txt"), L"Expected a.txt selected after restore-selection.");
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Right, L"C.TXT"), L"Expected C.TXT selected after restore-selection.");
    state.Require(! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Right, L"b.log"), L"Expected b.log not selected after restore-selection.");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Right) == 2u, L"Expected 2 selected items after restore-selection.");

    std::filesystem::remove(root / L"a.txt", ec);
    state.Require(! std::filesystem::exists(root / L"a.txt"), L"Failed to remove a.txt for restore-selection missing-item scenario.");

    {
        const uint32_t before = enumRight.load(std::memory_order_acquire);
        g_folderWindow.CommandRefresh(FolderWindow::Pane::Right);
        state.Require(WaitForAtomicAtLeast(enumRight, before + 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                      L"Right pane did not refresh after deleting a.txt.");
    }

    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(FolderWindow::Pane::Right, [](std::wstring_view) noexcept { return false; }, true);
    SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_SELECTION_RESTORE, 0), 0);

    state.Require(! g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Right, L"a.txt"),
                  L"Expected a.txt not selected after restore-selection when missing.");
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Right, L"C.TXT"),
                  L"Expected C.TXT selected after restore-selection when a.txt is missing.");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Right) == 1u,
                  L"Expected 1 selected item after restore-selection when a.txt is missing.");

    return state.failure.empty();
}

[[nodiscard]] bool TestCopyTextCommands(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"copy_text_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create copy-text test root.");

    state.Require(SelfTest::WriteTextFile(root / L"a.txt", "a"), L"Failed to create a.txt.");
    state.Require(SelfTest::WriteTextFile(root / L"b.log", "b"), L"Failed to create b.log.");
    state.Require(SelfTest::WriteTextFile(root / L"c.txt", "c"), L"Failed to create c.txt.");

    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const auto restorePath                                = wil::scope_exit([&]
    {
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to set local file-system plugin for copy-text test.");

    std::atomic<uint32_t> enumLeft{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumLeft.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Failed to set left pane path for copy-text test.");
    state.Require(WaitForAtomicAtLeast(enumLeft, 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Left pane enumeration did not complete for copy-text test.");
    state.Require(WaitForPaneItems(FolderWindow::Pane::Left, {L"a.txt", L"b.log", L"c.txt"}, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Left pane contents not ready for copy-text test.");

    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(
        FolderWindow::Pane::Left, [](std::wstring_view name) noexcept { return name == L"a.txt" || name == L"c.txt"; }, true);
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"a.txt"), L"Expected a.txt selected in copy-text test.");
    state.Require(g_folderWindow.DebugIsItemSelected(FolderWindow::Pane::Left, L"c.txt"), L"Expected c.txt selected in copy-text test.");
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 2u, L"Expected 2 selected items in copy-text test.");

    const std::wstring rootText = root.native();
    const std::wstring aFull    = (root / L"a.txt").native();
    const std::wstring cFull    = (root / L"c.txt").native();
    const std::wstring aUnc     = BuildLocalAdministrativeUncPath(aFull);
    const std::wstring cUnc     = BuildLocalAdministrativeUncPath(cFull);

    {
        ClearClipboardContents(mainWindow);
        FocusFolderViewPane(FolderWindow::Pane::Left);
        SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_COPY_PATH_AND_NAME_AS_TEXT, 0), 0);

        const std::wstring clipText = ReadClipboardUnicodeText(mainWindow);
        state.Require(! clipText.empty(), L"Expected Copy Path + Name as Text to place Unicode text in the clipboard.");
        state.Require(clipText.find(aFull) != std::wstring::npos, L"Expected clipboard text to contain full path for a.txt.");
        state.Require(clipText.find(cFull) != std::wstring::npos, L"Expected clipboard text to contain full path for c.txt.");
    }

    {
        ClearClipboardContents(mainWindow);
        FocusFolderViewPane(FolderWindow::Pane::Left);
        SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_COPY_NAME_AS_TEXT, 0), 0);

        const std::wstring clipText = ReadClipboardUnicodeText(mainWindow);
        state.Require(! clipText.empty(), L"Expected Copy Name as Text to place Unicode text in the clipboard.");
        state.Require(clipText.find(L"a.txt") != std::wstring::npos, L"Expected clipboard text to contain a.txt.");
        state.Require(clipText.find(L"c.txt") != std::wstring::npos, L"Expected clipboard text to contain c.txt.");
        state.Require(clipText.find(aFull) == std::wstring::npos, L"Expected name-only clipboard text to exclude the full path for a.txt.");
        state.Require(clipText.find(cFull) == std::wstring::npos, L"Expected name-only clipboard text to exclude the full path for c.txt.");
    }

    {
        ClearClipboardContents(mainWindow);
        FocusFolderViewPane(FolderWindow::Pane::Left);
        SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_COPY_PATH_AS_TEXT, 0), 0);

        const std::wstring clipText = ReadClipboardUnicodeText(mainWindow);
        state.Require(! clipText.empty(), L"Expected Copy Path as Text to place Unicode text in the clipboard.");
        state.Require(clipText.find(rootText) != std::wstring::npos, L"Expected clipboard text to contain the containing folder path.");
        state.Require(clipText.find(aFull) == std::wstring::npos, L"Expected path-only clipboard text to exclude the full path for a.txt.");
        state.Require(clipText.find(cFull) == std::wstring::npos, L"Expected path-only clipboard text to exclude the full path for c.txt.");
    }

    {
        ClearClipboardContents(mainWindow);
        FocusFolderViewPane(FolderWindow::Pane::Left);
        SendMessageW(mainWindow, WM_COMMAND, MAKEWPARAM(IDM_PANE_COPY_PATH_AND_FILE_NAME, 0), 0);

        const std::wstring clipText = ReadClipboardUnicodeText(mainWindow);
        state.Require(! clipText.empty(), L"Expected Copy UNC Path + Name as Text to place Unicode text in the clipboard.");
        state.Require(! aUnc.empty(), L"Expected a local-machine UNC path for a.txt in the UNC clipboard test.");
        state.Require(! cUnc.empty(), L"Expected a local-machine UNC path for c.txt in the UNC clipboard test.");
        state.Require(clipText.find(aUnc) != std::wstring::npos, L"Expected clipboard text to contain the UNC full path for a.txt.");
        state.Require(clipText.find(cUnc) != std::wstring::npos, L"Expected clipboard text to contain the UNC full path for c.txt.");
    }

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewRenderingErrorOverlayRequiresPersistence(HWND mainWindow, CaseState& state) noexcept
{
    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for FolderView rendering-error overlay persistence test.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for FolderView rendering-error overlay persistence test.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"folderview_rendering_error_overlay_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create FolderView rendering-error overlay fixture root.");
    if (! state.failure.empty())
    {
        return false;
    }

    constexpr HRESULT kRenderingFailureHr = HRESULT_FROM_WIN32(ERROR_DEVICE_NOT_CONNECTED);
    constexpr uint64_t kPersistentAgeMs   = 2500u;
    const auto cleanup                    = wil::scope_exit([&]
    {
        g_folderWindow.DebugClearPaneRenderingFailureForSelfTest(FolderWindow::Pane::Left);
        g_folderWindow.DebugHideOverlaySample(FolderWindow::Pane::Left);
        g_folderWindow.DismissPaneAlertOverlay(FolderWindow::Pane::Left);
    });

    auto describeSnapshot = [](const FolderView::AlertOverlayDebugSnapshot& snapshot)
    {
        return std::format(L"visible={} kind={} severity={} hr=0x{:08X} title='{}'",
                           snapshot.visible ? L"yes" : L"no",
                           static_cast<unsigned>(snapshot.kind),
                           static_cast<unsigned>(snapshot.severity),
                           static_cast<unsigned>(snapshot.hr),
                           snapshot.title);
    };
    auto captureSnapshot = [&](FolderView::AlertOverlayDebugSnapshot& snapshot, std::wstring_view context)
    {
        state.Require(g_folderWindow.DebugGetPaneAlertSnapshot(FolderWindow::Pane::Left, snapshot),
                      std::format(L"Failed to capture FolderView alert snapshot after {}.", context));
        return state.failure.empty();
    };

    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    g_folderWindow.DismissPaneAlertOverlay(FolderWindow::Pane::Left);
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to set local file-system plugin for FolderView rendering-error overlay persistence test.");
    if (! state.failure.empty())
    {
        return false;
    }

    std::atomic<uint32_t> enumRoot{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumRoot.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Failed to set left pane path for FolderView rendering-error overlay persistence test.");
    state.Require(WaitForAtomicAtLeast(enumRoot, 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Enumeration did not complete for FolderView rendering-error overlay persistence test.");
    if (! state.failure.empty())
    {
        return false;
    }

    g_folderWindow.DismissPaneAlertOverlay(FolderWindow::Pane::Left);
    g_folderWindow.DebugHideOverlaySample(FolderWindow::Pane::Left);
    g_folderWindow.DebugClearPaneRenderingFailureForSelfTest(FolderWindow::Pane::Left);
    PumpPendingMessages();

    FolderView::AlertOverlayDebugSnapshot snapshot{};
    if (! captureSnapshot(snapshot, L"initial clear"))
    {
        return false;
    }
    state.Require(! snapshot.visible, std::format(L"Expected no initial FolderView alert; {}.", describeSnapshot(snapshot)));
    if (! state.failure.empty())
    {
        return false;
    }

    for (int attempt = 1; attempt <= 2; ++attempt)
    {
        g_folderWindow.DebugReportPaneRenderingFailureForSelfTest(FolderWindow::Pane::Left, kRenderingFailureHr);
        if (! captureSnapshot(snapshot, std::format(L"transient rendering failure attempt {}", attempt)))
        {
            return false;
        }
        state.Require(
            ! snapshot.visible,
            std::format(L"Transient rendering failure attempt {} unexpectedly created a user-visible alert; {}.", attempt, describeSnapshot(snapshot)));
    }
    if (! state.failure.empty())
    {
        return false;
    }

    g_folderWindow.DebugAgePaneRenderingFailureForSelfTest(FolderWindow::Pane::Left, kPersistentAgeMs);
    g_folderWindow.DebugReportPaneRenderingFailureForSelfTest(FolderWindow::Pane::Left, kRenderingFailureHr);
    if (! captureSnapshot(snapshot, L"persistent rendering failure"))
    {
        return false;
    }

    state.Require(snapshot.visible, std::format(L"Persistent rendering failure did not create an alert; {}.", describeSnapshot(snapshot)));
    state.Require(snapshot.kind == FolderView::ErrorOverlayKind::Rendering,
                  std::format(L"Persistent rendering failure alert used the wrong kind; {}.", describeSnapshot(snapshot)));
    state.Require(snapshot.severity == FolderView::OverlaySeverity::Error,
                  std::format(L"Persistent rendering failure alert used the wrong severity; {}.", describeSnapshot(snapshot)));
    state.Require(snapshot.hr == kRenderingFailureHr,
                  std::format(L"Persistent rendering failure alert used the wrong HRESULT; {}.", describeSnapshot(snapshot)));
    const std::wstring renderingTitle = LoadStringResource(nullptr, IDS_OVERLAY_TITLE_RENDERING_ERROR);
    if (! renderingTitle.empty())
    {
        state.Require(snapshot.title == renderingTitle,
                      std::format(L"Persistent rendering failure alert title mismatch; expected='{}' actual='{}'.", renderingTitle, snapshot.title));
    }
    if (! state.failure.empty())
    {
        return false;
    }

    g_folderWindow.DebugClearPaneRenderingFailureForSelfTest(FolderWindow::Pane::Left);
    PumpPendingMessages();
    if (! captureSnapshot(snapshot, L"rendering failure clear"))
    {
        return false;
    }
    state.Require(! snapshot.visible, std::format(L"Rendering failure alert stayed visible after clear; {}.", describeSnapshot(snapshot)));
    if (! state.failure.empty())
    {
        return false;
    }

    g_folderWindow.DebugReportPaneRenderingFailureForSelfTest(FolderWindow::Pane::Left, kRenderingFailureHr);
    if (! captureSnapshot(snapshot, L"post-clear transient rendering failure"))
    {
        return false;
    }
    state.Require(! snapshot.visible, std::format(L"Rendering failure persistence gate did not reset after clear; {}.", describeSnapshot(snapshot)));

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewRefreshToPaintMetricClearsAfterFailedRender(HWND mainWindow, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for FolderView refresh-to-paint stale metric test.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for FolderView refresh-to-paint stale metric test.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"folderview_refresh_to_paint_failed_render_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create FolderView refresh-to-paint fixture root.");
    state.Require(SelfTest::WriteTextFile(root / L"alpha.txt", "alpha"), L"Failed to create alpha.txt for FolderView refresh-to-paint fixture.");
    state.Require(SelfTest::WriteTextFile(root / L"beta.txt", "beta"), L"Failed to create beta.txt for FolderView refresh-to-paint fixture.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const FolderView::DisplayMode displayBefore           = g_folderWindow.GetDisplayMode(FolderWindow::Pane::Left);
    const FolderView::SortBy sortBefore                   = g_folderWindow.GetSortBy(FolderWindow::Pane::Left);
    const FolderView::SortDirection directionBefore       = g_folderWindow.GetSortDirection(FolderWindow::Pane::Left);
    const auto restoreState                               = wil::scope_exit([&]
    {
        g_folderWindow.DebugClearPaneRenderingFailureForSelfTest(FolderWindow::Pane::Left);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, displayBefore);
        g_folderWindow.SetSort(FolderWindow::Pane::Left, sortBefore, directionBefore);
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to set local file-system plugin for FolderView refresh-to-paint stale metric test.");
    g_folderWindow.SetDisplayMode(FolderWindow::Pane::Left, FolderView::DisplayMode::Detailed);
    g_folderWindow.SetSort(FolderWindow::Pane::Left, FolderView::SortBy::Name, FolderView::SortDirection::Ascending);
    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    if (! state.failure.empty())
    {
        return false;
    }

    std::atomic<uint32_t> enumRoot{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumRoot.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(3000ms)),
                  L"Failed to set left pane path for FolderView refresh-to-paint stale metric test.");
    state.Require(WaitForAtomicAtLeast(enumRoot, 1u, SelfTest::Scale(3000ms)),
                  L"Initial enumeration did not complete for FolderView refresh-to-paint stale metric test.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, 2u, SelfTest::Scale(3000ms)),
                  L"FolderView refresh-to-paint fixture did not show the expected item count.");
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left),
                  L"Failed to warm initial FolderView rendering before refresh-to-paint failure injection.");
    if (! state.failure.empty())
    {
        return false;
    }

    HWND folderView = g_folderWindow.GetFolderViewHwnd(FolderWindow::Pane::Left);
    state.Require(folderView && IsWindow(folderView), L"FolderView hwnd unavailable for refresh-to-paint stale metric test.");
    if (! folderView || IsWindow(folderView) == FALSE)
    {
        return false;
    }

    const std::uintmax_t metricScanOffset = FolderViewPerfMetricScanOffset();
    const uint64_t inputMetricBefore      = FolderViewPerfMetricCountInRun(L"folder.frame.input_to_paint_us", metricScanOffset);
    FocusFolderViewPane(FolderWindow::Pane::Left);
    PumpPendingMessages();
    const std::wstring focusBeforeInput = std::wstring(g_folderWindow.DebugGetFocusedItemDisplayName(FolderWindow::Pane::Left));
    const WPARAM navigationKey          = focusBeforeInput == L"beta.txt" ? VK_UP : VK_DOWN;
    g_folderWindow.DebugForcePaneNextRenderFailure(FolderWindow::Pane::Left, FolderView::DebugRenderFailurePoint::EndDraw, E_FAIL);
    static_cast<void>(SendMessageW(folderView, WM_KEYDOWN, navigationKey, 1));
    const std::wstring focusAfterInput = std::wstring(g_folderWindow.DebugGetFocusedItemDisplayName(FolderWindow::Pane::Left));
    state.Require(focusAfterInput != focusBeforeInput,
                  std::format(L"FolderView input-to-paint failure proof must move focus; before='{}' after='{}'.",
                              focusBeforeInput,
                              focusAfterInput));
    UpdateWindow(folderView);
    const uint64_t inputMetricAfterFailedPaint = FolderViewPerfMetricCountInRun(L"folder.frame.input_to_paint_us", metricScanOffset);
    state.Require(inputMetricAfterFailedPaint == inputMetricBefore,
                  std::format(L"Input-to-paint metric emitted during failed EndDraw paint; before={} after={}.",
                              inputMetricBefore,
                              inputMetricAfterFailedPaint));
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left),
                  L"Failed to warm render after the failed input-to-paint paint.");
    const uint64_t inputMetricAfterLaterPresent = FolderViewPerfMetricCountInRun(L"folder.frame.input_to_paint_us", metricScanOffset);
    state.Require(inputMetricAfterLaterPresent == inputMetricBefore,
                  std::format(L"Stale input-to-paint metric emitted on an unrelated later Present; before={} after={}.",
                              inputMetricBefore,
                              inputMetricAfterLaterPresent));
    if (! state.failure.empty())
    {
        return false;
    }

    const uint64_t metricBefore           = FolderViewPerfMetricCountInRun(L"folder.refresh.request_to_paint_us", metricScanOffset);
    const uint32_t enumBefore             = enumRoot.load(std::memory_order_acquire);
    const uint64_t refreshBefore          = g_folderWindow.DebugGetForceRefreshCount(FolderWindow::Pane::Left);

    g_folderWindow.CommandRefresh(FolderWindow::Pane::Left);
    state.Require(WaitForAtomicAtLeastWithoutWindowPaint(enumRoot, enumBefore + 1u, folderView, SelfTest::Scale(5000ms)),
                  L"Refresh enumeration did not complete before paint for FolderView refresh-to-paint stale metric test.");
    state.Require(g_folderWindow.DebugGetForceRefreshCount(FolderWindow::Pane::Left) >= refreshBefore + 1u,
                  L"FolderView refresh-to-paint test did not increment the force-refresh count.");
    state.Require(g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left) == 2u,
                  std::format(L"FolderView refresh-to-paint fixture item count changed unexpectedly; count={}.",
                              g_folderWindow.DebugGetItemCount(FolderWindow::Pane::Left)));
    state.Require(FolderViewPerfMetricCountInRun(L"folder.refresh.request_to_paint_us", metricScanOffset) == metricBefore,
                  L"Refresh-to-paint metric fired before the scripted paint failure.");
    if (! state.failure.empty())
    {
        return false;
    }

    g_folderWindow.DebugForcePaneNextRenderFailure(FolderWindow::Pane::Left, FolderView::DebugRenderFailurePoint::EndDraw, E_FAIL);
    InvalidateRect(folderView, nullptr, FALSE);
    UpdateWindow(folderView);
    const uint64_t metricAfterFailedPaint = FolderViewPerfMetricCountInRun(L"folder.refresh.request_to_paint_us", metricScanOffset);
    state.Require(metricAfterFailedPaint == metricBefore,
                  std::format(L"Refresh-to-paint metric emitted during failed EndDraw paint; before={} after={}.",
                              metricBefore,
                              metricAfterFailedPaint));
    if (! state.failure.empty())
    {
        return false;
    }

    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left),
                  L"Failed to warm render after the failed refresh-to-paint paint.");
    const uint64_t metricAfterLaterPresent = FolderViewPerfMetricCountInRun(L"folder.refresh.request_to_paint_us", metricScanOffset);
    state.Require(metricAfterLaterPresent == metricBefore,
                  std::format(L"Stale refresh-to-paint metric emitted on an unrelated later Present; before={} after={}.",
                              metricBefore,
                              metricAfterLaterPresent));

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewRenderDeviceLossRecovers(HWND mainWindow, CaseState& state) noexcept
{
    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for FolderView device-loss recovery test.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for FolderView device-loss recovery test.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"folderview_render_device_loss_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create FolderView device-loss fixture root.");
    state.Require(SelfTest::WriteTextFile(root / L"alpha.txt", "alpha"), L"Failed to create alpha.txt for FolderView device-loss fixture.");
    state.Require(SelfTest::WriteTextFile(root / L"beta.txt", "beta"), L"Failed to create beta.txt for FolderView device-loss fixture.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const auto cleanup                                    = wil::scope_exit([&]
    {
        g_folderWindow.DebugClearPaneRenderingFailureForSelfTest(FolderWindow::Pane::Left);
        g_folderWindow.DismissPaneAlertOverlay(FolderWindow::Pane::Left);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    auto describeRendering = [](const FolderView::RenderingDebugSnapshot& snapshot)
    {
        return std::format(L"client={}x{} target={} resizePending={} forceFull={} lastFull={} fullCount={} recoveries={} discarded={} lastRect=({},{}-{},{} )",
                           snapshot.clientSizePx.cx,
                           snapshot.clientSizePx.cy,
                           snapshot.hasD2DTarget ? L"yes" : L"no",
                           snapshot.swapChainResizePending ? L"yes" : L"no",
                           snapshot.forceFullRenderOnNextPaint ? L"yes" : L"no",
                           snapshot.lastRenderWasFullClient ? L"yes" : L"no",
                           snapshot.fullClientRenderCount,
                           snapshot.deviceLossRecoveryCount,
                           snapshot.deviceLossDiscardedResourcesCount,
                           snapshot.lastRenderInvalidRectPx.left,
                           snapshot.lastRenderInvalidRectPx.top,
                           snapshot.lastRenderInvalidRectPx.right,
                           snapshot.lastRenderInvalidRectPx.bottom);
    };

    auto assertNoAlert = [&](std::wstring_view context)
    {
        FolderView::AlertOverlayDebugSnapshot alert{};
        state.Require(g_folderWindow.DebugGetPaneAlertSnapshot(FolderWindow::Pane::Left, alert),
                      std::format(L"Failed to capture FolderView alert snapshot after {}.", context));
        state.Require(! alert.visible,
                      std::format(L"FolderView rendering alert remained visible after {}; kind={} hr=0x{:08X} title='{}'.",
                                  context,
                                  static_cast<unsigned>(alert.kind),
                                  static_cast<unsigned>(alert.hr),
                                  alert.title));
    };

    auto assertRecovered = [&](FolderView::DebugRenderFailurePoint point,
                               HRESULT forcedHr,
                               std::wstring_view context,
                               const FolderView::RenderingDebugSnapshot& before)
    {
        g_folderWindow.DebugForcePaneNextRenderFailure(FolderWindow::Pane::Left, point, forcedHr);
        state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left),
                      std::format(L"Failed to warm-render after injected {} device loss.", context));
        PumpPendingMessages();

        const FolderView::RenderingDebugSnapshot after = g_folderWindow.DebugGetPaneRenderingSnapshot(FolderWindow::Pane::Left);
        state.Require(after.hasD2DTarget, std::format(L"FolderView target missing after {} recovery; {}.", context, describeRendering(after)));
        state.Require(! after.swapChainResizePending,
                      std::format(L"FolderView still has a pending swap-chain resize after {} recovery; {}.", context, describeRendering(after)));
        state.Require(! after.forceFullRenderOnNextPaint,
                      std::format(L"FolderView did not clear the forced-full-render flag after {} recovery; {}.", context, describeRendering(after)));
        state.Require(after.fullClientRenderCount > before.fullClientRenderCount,
                      std::format(L"FolderView full-client render count did not increase after {} recovery; before={} after={}.",
                                  context,
                                  before.fullClientRenderCount,
                                  describeRendering(after)));
        state.Require(after.deviceLossRecoveryCount == before.deviceLossRecoveryCount + 1u,
                      std::format(L"FolderView device-loss recovery counter mismatch after {}; before={} after={}.",
                                  context,
                                  before.deviceLossRecoveryCount,
                                  after.deviceLossRecoveryCount));
        state.Require(after.deviceLossDiscardedResourcesCount == before.deviceLossDiscardedResourcesCount + 1u,
                      std::format(L"FolderView did not prove device resources were discarded after {}; before={} after={}.",
                                  context,
                                  before.deviceLossDiscardedResourcesCount,
                                  after.deviceLossDiscardedResourcesCount));
        assertNoAlert(context);
    };

    g_folderWindow.DebugResetPaneVisibilityState(FolderWindow::Pane::Left);
    g_folderWindow.DismissPaneAlertOverlay(FolderWindow::Pane::Left);
    g_folderWindow.DebugClearPaneRenderingFailureForSelfTest(FolderWindow::Pane::Left);
    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to set local file-system plugin for FolderView device-loss recovery test.");
    if (! state.failure.empty())
    {
        return false;
    }

    std::atomic<uint32_t> enumRoot{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumRoot.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Failed to set left pane path for FolderView device-loss recovery test.");
    state.Require(WaitForAtomicAtLeast(enumRoot, 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Enumeration did not complete for FolderView device-loss recovery test.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, 2u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"FolderView device-loss fixture did not show the expected item count.");
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left), L"Failed to warm initial FolderView rendering before device-loss injection.");
    assertNoAlert(L"initial warm render");
    if (! state.failure.empty())
    {
        return false;
    }

    const FolderView::RenderingDebugSnapshot beforeEndDraw = g_folderWindow.DebugGetPaneRenderingSnapshot(FolderWindow::Pane::Left);
    assertRecovered(FolderView::DebugRenderFailurePoint::EndDraw, DXGI_ERROR_DEVICE_REMOVED, L"EndDraw", beforeEndDraw);
    if (! state.failure.empty())
    {
        return false;
    }

    const FolderView::RenderingDebugSnapshot beforePresent = g_folderWindow.DebugGetPaneRenderingSnapshot(FolderWindow::Pane::Left);
    assertRecovered(FolderView::DebugRenderFailurePoint::Present, DXGI_ERROR_DEVICE_REMOVED, L"Present", beforePresent);

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewDrawItemBrushReuseGuard(HWND mainWindow, CaseState& state) noexcept
{
    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for FolderView draw-item brush reuse guard.");
        return false;
    }

    const std::filesystem::path suiteRoot = SelfTest::GetTempRoot(SelfTest::SelfTestSuite::Commands);
    state.Require(! suiteRoot.empty(), L"SelfTest temp root unavailable for FolderView draw-item brush reuse guard.");
    if (suiteRoot.empty())
    {
        return false;
    }

    const std::filesystem::path root = suiteRoot / L"work" / (L"folderview_draw_item_brush_reuse_" + NewGuidText());
    std::error_code ec;
    std::filesystem::remove_all(root, ec);
    state.Require(SelfTest::EnsureDirectory(root), L"Failed to create FolderView brush-reuse fixture root.");
    state.Require(SelfTest::WriteTextFile(root / L"alpha.txt", "alpha"), L"Failed to create alpha.txt for FolderView brush-reuse fixture.");
    state.Require(SelfTest::WriteTextFile(root / L"beta.txt", "beta"), L"Failed to create beta.txt for FolderView brush-reuse fixture.");
    state.Require(SelfTest::WriteTextFile(root / L"gamma.txt", "gamma"), L"Failed to create gamma.txt for FolderView brush-reuse fixture.");
    state.Require(SelfTest::WriteTextFile(root / L"hover.txt", "hover"), L"Failed to create hover.txt for FolderView brush-reuse fixture.");
    if (! state.failure.empty())
    {
        return false;
    }

    const std::optional<std::filesystem::path> leftBefore = g_folderWindow.GetCurrentPath(FolderWindow::Pane::Left);
    const std::wstring leftPluginBefore                   = std::wstring(g_folderWindow.GetFileSystemPluginId(FolderWindow::Pane::Left));
    const auto cleanup                                    = wil::scope_exit([&]
    {
        g_folderWindow.DebugResetPaneDrawItemTransientBrushCreateCount(FolderWindow::Pane::Left);
        static_cast<void>(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, leftPluginBefore));
        if (leftBefore.has_value())
        {
            g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, leftBefore.value());
        }
    });

    state.Require(SUCCEEDED(g_folderWindow.SetFileSystemPluginForPane(FolderWindow::Pane::Left, L"builtin/file-system")),
                  L"Failed to set local file-system plugin for FolderView brush-reuse guard.");
    if (! state.failure.empty())
    {
        return false;
    }

    std::atomic<uint32_t> enumRoot{0};
    g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left,
                                                       [&](const std::filesystem::path& folder) noexcept
    {
        if (OrdinalString::EqualsNoCasePath(folder, root))
        {
            enumRoot.fetch_add(1u, std::memory_order_release);
        }
    });
    const auto clearEnumCallback = wil::scope_exit([&] { g_folderWindow.SetPaneEnumerationCompletedCallback(FolderWindow::Pane::Left, {}); });

    g_folderWindow.SetFolderPath(FolderWindow::Pane::Left, root);
    state.Require(WaitForPanePath(FolderWindow::Pane::Left, root, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Failed to set left pane path for FolderView brush-reuse guard.");
    state.Require(WaitForAtomicAtLeast(enumRoot, 1u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"Enumeration did not complete for FolderView brush-reuse guard.");
    state.Require(WaitForFolderViewItemCount(FolderWindow::Pane::Left, 4u, SelfTest::Scale(std::chrono::milliseconds{3000})),
                  L"FolderView brush-reuse fixture did not show the expected item count.");
    if (! state.failure.empty())
    {
        return false;
    }

    FocusFolderViewPane(FolderWindow::Pane::Left);
    g_folderWindow.SetPaneSelectionByDisplayNamePredicate(
        FolderWindow::Pane::Left,
        [](std::wstring_view name) noexcept { return name == L"alpha.txt" || name == L"beta.txt" || name == L"gamma.txt"; },
        true);
    state.Require(g_folderWindow.DebugGetSelectedCount(FolderWindow::Pane::Left) == 3u,
                  L"FolderView brush-reuse guard failed to create a wide selected set.");
    state.Require(g_folderWindow.DebugSetPaneHoveredItemByDisplayName(FolderWindow::Pane::Left, L"hover.txt"),
                  L"FolderView brush-reuse guard failed to set an unselected hovered item.");
    if (! state.failure.empty())
    {
        return false;
    }

    g_folderWindow.DebugResetPaneDrawItemTransientBrushCreateCount(FolderWindow::Pane::Left);
    state.Require(g_folderWindow.DebugWarmPaneRendering(FolderWindow::Pane::Left),
                  L"Failed to warm-render FolderView brush-reuse guard.");

    const FolderView::RenderingDebugSnapshot snapshot = g_folderWindow.DebugGetPaneRenderingSnapshot(FolderWindow::Pane::Left);
    Debug::Perf::Emit(L"folder.draw_item.transient_brush_create_count",
                      L"selected-hovered-redraw",
                      0u,
                      snapshot.drawItemTransientBrushCreateCount,
                      4u,
                      snapshot.drawItemTransientBrushCreateCount == 0u ? S_OK : E_FAIL);
    state.Require(snapshot.drawItemTransientBrushCreateCount == 0u,
                  std::format(L"DrawItem created {} transient D2D brush(es) while rendering selected/hovered items.",
                              snapshot.drawItemTransientBrushCreateCount));
    if (! state.failure.empty())
    {
        return false;
    }

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewDpiChangeRepaintsBothPanes(HWND mainWindow, CaseState& state) noexcept
{
    if (! mainWindow || ! IsWindow(mainWindow))
    {
        state.Require(false, L"Main window handle invalid for FolderView DPI repaint test.");
        return false;
    }

    const UINT actualWindowDpi = GetDpiForWindow(mainWindow);
    const float originalDpi    = actualWindowDpi > 0u ? static_cast<float>(actualWindowDpi) : 96.0f;
    const float testDpi        = std::abs(originalDpi - 144.0f) > 0.5f ? 144.0f : 96.0f;

    auto repaintPane = [&](FolderWindow::Pane pane) noexcept
    {
        const HWND folderView = g_folderWindow.GetFolderViewHwnd(pane);
        if (folderView && IsWindow(folderView) != FALSE)
        {
            RedrawWindow(folderView, nullptr, nullptr, RDW_INVALIDATE | RDW_UPDATENOW | RDW_ALLCHILDREN);
        }
    };
    const auto restoreDpi = wil::scope_exit([&]
    {
        g_folderWindow.OnDpiChanged(originalDpi);
        repaintPane(FolderWindow::Pane::Left);
        repaintPane(FolderWindow::Pane::Right);
        PumpPendingMessages();
    });

    auto describeRendering = [](const FolderView::RenderingDebugSnapshot& snapshot)
    {
        return std::format(L"dpi={} client={}x{} target={} resizePending={} forceFull={} lastFull={} fullCount={} lastRect=({},{}-{},{} )",
                           snapshot.dpi,
                           snapshot.clientSizePx.cx,
                           snapshot.clientSizePx.cy,
                           snapshot.hasD2DTarget ? L"yes" : L"no",
                           snapshot.swapChainResizePending ? L"yes" : L"no",
                           snapshot.forceFullRenderOnNextPaint ? L"yes" : L"no",
                           snapshot.lastRenderWasFullClient ? L"yes" : L"no",
                           snapshot.fullClientRenderCount,
                           snapshot.lastRenderInvalidRectPx.left,
                           snapshot.lastRenderInvalidRectPx.top,
                           snapshot.lastRenderInvalidRectPx.right,
                           snapshot.lastRenderInvalidRectPx.bottom);
    };

    auto assertPaneReady = [&](FolderWindow::Pane pane, std::wstring_view name)
    {
        const HWND folderView = g_folderWindow.GetFolderViewHwnd(pane);
        state.Require(folderView && IsWindow(folderView) != FALSE, std::format(L"{} FolderView hwnd invalid for DPI repaint test.", name));
        state.Require(g_folderWindow.DebugWarmPaneRendering(pane), std::format(L"Failed to warm {} FolderView rendering before DPI repaint test.", name));
        const FolderView::RenderingDebugSnapshot snapshot = g_folderWindow.DebugGetPaneRenderingSnapshot(pane);
        state.Require(snapshot.clientSizePx.cx > 0 && snapshot.clientSizePx.cy > 0,
                      std::format(L"{} FolderView client is empty before DPI repaint test; {}.", name, describeRendering(snapshot)));
        state.Require(snapshot.hasD2DTarget, std::format(L"{} FolderView target missing before DPI repaint test; {}.", name, describeRendering(snapshot)));
    };

    assertPaneReady(FolderWindow::Pane::Left, L"Left");
    assertPaneReady(FolderWindow::Pane::Right, L"Right");
    if (! state.failure.empty())
    {
        return false;
    }

    const FolderView::RenderingDebugSnapshot leftBefore  = g_folderWindow.DebugGetPaneRenderingSnapshot(FolderWindow::Pane::Left);
    const FolderView::RenderingDebugSnapshot rightBefore = g_folderWindow.DebugGetPaneRenderingSnapshot(FolderWindow::Pane::Right);

    g_folderWindow.OnDpiChanged(testDpi);

    const FolderView::RenderingDebugSnapshot leftPending  = g_folderWindow.DebugGetPaneRenderingSnapshot(FolderWindow::Pane::Left);
    const FolderView::RenderingDebugSnapshot rightPending = g_folderWindow.DebugGetPaneRenderingSnapshot(FolderWindow::Pane::Right);
    const bool leftScheduledOrPainted  = leftPending.forceFullRenderOnNextPaint || leftPending.fullClientRenderCount > leftBefore.fullClientRenderCount;
    const bool rightScheduledOrPainted = rightPending.forceFullRenderOnNextPaint || rightPending.fullClientRenderCount > rightBefore.fullClientRenderCount;
    state.Require(std::abs(leftPending.dpi - testDpi) <= 0.5f,
                  std::format(L"Left FolderView DPI did not update before repaint; {}.", describeRendering(leftPending)));
    state.Require(std::abs(rightPending.dpi - testDpi) <= 0.5f,
                  std::format(L"Right FolderView DPI did not update before repaint; {}.", describeRendering(rightPending)));
    state.Require(leftScheduledOrPainted,
                  std::format(L"Left FolderView neither scheduled nor completed a full repaint for DPI change; beforeFullCount={} after={}.",
                              leftBefore.fullClientRenderCount,
                              describeRendering(leftPending)));
    state.Require(rightScheduledOrPainted,
                  std::format(L"Right FolderView neither scheduled nor completed a full repaint for DPI change; beforeFullCount={} after={}.",
                              rightBefore.fullClientRenderCount,
                              describeRendering(rightPending)));
    if (! state.failure.empty())
    {
        return false;
    }

    repaintPane(FolderWindow::Pane::Left);
    repaintPane(FolderWindow::Pane::Right);
    PumpPendingMessages();

    auto assertPaneRepainted = [&](FolderWindow::Pane pane, std::wstring_view name, const FolderView::RenderingDebugSnapshot& before)
    {
        const FolderView::RenderingDebugSnapshot after = g_folderWindow.DebugGetPaneRenderingSnapshot(pane);
        state.Require(std::abs(after.dpi - testDpi) <= 0.5f, std::format(L"{} FolderView DPI changed after repaint; {}.", name, describeRendering(after)));
        state.Require(after.hasD2DTarget, std::format(L"{} FolderView target missing after DPI repaint; {}.", name, describeRendering(after)));
        state.Require(! after.swapChainResizePending, std::format(L"{} FolderView still has pending swap-chain resize; {}.", name, describeRendering(after)));
        state.Require(! after.forceFullRenderOnNextPaint,
                      std::format(L"{} FolderView did not clear full repaint flag after present; {}.", name, describeRendering(after)));
        state.Require(after.fullClientRenderCount > before.fullClientRenderCount,
                      std::format(L"{} FolderView full-client render count did not increase; before={} after={}.",
                                  name,
                                  before.fullClientRenderCount,
                                  after.fullClientRenderCount));
    };

    assertPaneRepainted(FolderWindow::Pane::Left, L"Left", leftBefore);
    assertPaneRepainted(FolderWindow::Pane::Right, L"Right", rightBefore);

    return state.failure.empty();
}

[[nodiscard]] bool TestFolderViewDebugLatencyHooksConsumeOnce(HWND /*mainWindow*/, CaseState& state) noexcept
{
    using namespace std::chrono_literals;

    SelfTestLatency::ClearAll();
    auto cleanup = wil::scope_exit([] { SelfTestLatency::ClearAll(); });

    SelfTestLatency::SetNextDelay(SelfTestLatency::Point::ShellThumbnailProviderAllowed, 25ms);

    const auto firstStart = std::chrono::steady_clock::now();
    SelfTestLatency::Consume(SelfTestLatency::Point::ShellThumbnailProviderAllowed);
    const auto firstElapsed = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - firstStart);

    state.Require(firstElapsed >= 20ms, std::format(L"First latency hook consume was too short: {} ms.", firstElapsed.count()));
    state.Require(firstElapsed < 500ms, std::format(L"First latency hook consume exceeded the smoke-test ceiling: {} ms.", firstElapsed.count()));

    const auto secondStart = std::chrono::steady_clock::now();
    SelfTestLatency::Consume(SelfTestLatency::Point::ShellThumbnailProviderAllowed);
    const auto secondElapsed = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - secondStart);

    state.Require(secondElapsed < 50ms, std::format(L"Second latency hook consume should not sleep again: {} ms.", secondElapsed.count()));
    state.Require(SelfTestLatency::ConsumeCount(SelfTestLatency::Point::ShellThumbnailProviderAllowed) == 2u,
                  L"Latency hook consume count should include both consume calls.");

    return true;
}

